export const getDeleteApplicationVersionUrl = (
  projectId: string,
  applicationId: number,
  versionId: number,
  params?: DeleteApplicationVersionParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/elitea_core/version/prompt_lib/${projectId}/${applicationId}/${versionId}?${stringifiedParams}`
    : `/elitea_core/version/prompt_lib/${projectId}/${applicationId}/${versionId}`;
};

